    aiBimModeReady: { ja: '抽出結果を確認し、問題なければ「確認して足場モデルを作成」を押してください。', en: 'Review the extracted result, then click "Confirm & Create Scaffold Model" if everything looks correct.', fr: 'Verifiez le resultat extrait, puis cliquez sur « Confirmer et creer le modele d\'echafaudage » si tout semble correct.' },
    aiBimModeDescription: { ja: 'IFC、DXF、画像、またはPDFをアップロードすると、建物の外形と寸法を自動検出し、確認後に足場モデルとBOMを生成します。', en: 'Upload an IFC, DXF, image, or PDF file. The system will auto-detect the building outline and dimensions, then generate a scaffold model and BOM after confirmation.', fr: 'Televersez un fichier IFC, DXF, image ou PDF. Le systeme detectera automatiquement le contour et les dimensions du batiment, puis generera un modele d\'echafaudage et une nomenclature apres confirmation.' },
    aiBimColorSamplingHint: { ja: 'BIM画像の場合、3Dビューの建物色をアップロード画像から自動サンプリングします。', en: 'For BIM images, the building color in the 3D view is auto-sampled from the uploaded file.', fr: 'Pour les images BIM, la couleur du batiment dans la vue 3D est automatiquement echantillonnee depuis le fichier televerse.' },
